const LEVEL_ORDER = {
    silent: 0,
    error: 1,
    warn: 2,
    info: 3,
    debug: 4,
};
let currentLevel = "warn";
export function setKeyhiveLogLevel(level) {
    currentLevel = level;
}
export function getKeyhiveLogLevel() {
    return currentLevel;
}
function enabled(level) {
    return LEVEL_ORDER[currentLevel] >= LEVEL_ORDER[level];
}
export const log = {
    error(...args) {
        if (enabled("error"))
            console.error(...args);
    },
    warn(...args) {
        if (enabled("warn"))
            console.warn(...args);
    },
    info(...args) {
        if (enabled("info"))
            console.log(...args);
    },
    debug(...args) {
        if (enabled("debug"))
            console.debug(...args);
    },
};
